from pathlib import Path
import os,sys,subprocess,json,shutil,hashlib
r=Path('/home/claude/code/EKA2L1');s=Path('/home/claude/.scratch/eka-benchmark');a=s/'tail-prefix-candidate'
e=dict(os.environ,PUPPETEER_EXECUTABLE_PATH='/usr/bin/chromium',EKA2L1_WASM_BUILD_DIR=str(a),EKA2L1_AOT_IR_MODE='7',EKA2L1_AOT_EAGER_REGIONS='0',EKA2L1_TLB_HASH='1',EKA2L1_SHARED_AUDIO='1',EKA2L1_BENCHMARK_AOT='5',EKA2L1_AOT_VERIFY='1024',EKA2L1_CODE_COMPARE='2',EKA2L1_CODE_LOOKUP='0',EKA2L1_EXECUTION_LIMITS='512,16,8,512',EKA2L1_PREDICATED_LEAVES='1',EKA2L1_EXIT_CENSUS='0')
for k in ['LD_LIBRARY_PATH','EKA2L1_CODE_WRITE_PROTECT','EKA2L1_GUEST_PROFILE','EKA2L1_AOT_DIAGNOSTICS']:e.pop(k,None)
def run(args,name,cwd=r,env=e):
 with(s/name).open('w')as log:subprocess.run(args,cwd=cwd,env=env,stdout=log,stderr=subprocess.STDOUT,check=True,timeout=3600)
 print(name+' PASS',flush=True)
stage=sys.argv[-1]
if stage=='archive':
 a.mkdir();(a/'tests').mkdir()
 for name in ['eka2l1.js','eka2l1.wasm','eka2l1.data','eka2l1.html','audio.js','audio-worklet.js']:shutil.copy2(r/'build-wasm/src/emu/wasm'/name,a/name)
 for name in ['test_aot_wasm.js','test_aot_wasm.wasm','eka_cpu_fault_wasm.js','eka_cpu_fault_wasm.wasm']:shutil.copy2(r/'build-wasm/src/tests/aot'/name,a/'tests'/name)
 for name in ['eka_cpu_fault_native','eka_cpu_tests']:shutil.copy2(r/'build/src/tests'/name,a/'tests'/name)
 (a/'source.patch').write_bytes(subprocess.check_output(['git','diff','HEAD','--binary'],cwd=r))
 (a/'source.json').write_text(json.dumps(dict(base=subprocess.check_output(['git','rev-parse','HEAD'],cwd=r,text=True).strip(),files={str(p.relative_to(a)):hashlib.sha256(p.read_bytes()).hexdigest()for p in a.rglob('*')if p.is_file()}),indent=2)+'\n')
 run([str(a/'tests/eka_cpu_tests')],'tail-prefix-native-tests.log')
elif stage=='unit':run(['node',str(a/'tests/test_aot_wasm.js'),'--exit-census'],'tail-prefix-unit-instrumented.log')
elif stage=='faults':
 for name,mode in [('conditional',0),('candidate',64)]:
  run(['python3','src/tests/benchmark/run_cpu_fault_matrix.py',str(a),str(s/f'tail-prefix-fault-{name}'),'--ir-policy','7','--code-compare','2','--tlb-hash','1','--execution-limits','512,16,8,512','--predicated-leaves','1','--exit-census','0','--leaf-features',str(mode),'--tail-prefixes'],f'tail-prefix-fault-{name}.log')
elif stage=='replay':
 for name,mode,verify in [('control',0,1024),('candidate',64,1024),('normal',64,0)]:
  run(['node','benchmark.ts',str(s/'assets'),str(s/f'tail-prefix-replay-{name}'),'1600'],f'tail-prefix-replay-{name}.log',r/'src/tests/wasm',dict(e,EKA2L1_LEAF_FEATURES=str(mode),EKA2L1_AOT_VERIFY=str(verify)))
  run(['python3','src/tests/benchmark/compare.py',str(s/'merge-20260930-native/run-0/frames'),str(s/f'tail-prefix-replay-{name}')],f'tail-prefix-compare-{name}.json')
  v=json.loads((s/f'tail-prefix-compare-{name}.json').read_text());assert v['match'] and v['frames']==1600 and v['audio']['sample_frames']==4656051
  report=json.loads((s/f'tail-prefix-replay-{name}/report.json').read_text());assert not report['exit_census'] and report['predicated_leaves']==1 and report['leaf_features']==mode and report['ir_mode']==7 and report['execution_limits']==[512,16,8,512]
 run(['node','benchmark.ts',str(s/'assets'),str(s/'tail-prefix-long-replay'),'360',str(r/'src/tests/benchmark/snakes-length-long.input'),'42000000'],'tail-prefix-long-replay.log',r/'src/tests/wasm',dict(e,EKA2L1_LEAF_FEATURES='64'))
 run(['python3','src/tests/benchmark/compare.py',str(s/'merge-20260930-long-native/run-0/frames'),str(s/'tail-prefix-long-replay')],'tail-prefix-long-compare.json')
 assert json.loads((s/'tail-prefix-long-compare.json').read_text())['match']
